import unittest
from windows import merge


class TestWindows(unittest.TestCase):
    def test_contained(self):
        self.assertEqual(merge([(1, 9), (3, 5)]), [(1, 9)])

    def test_touching(self):
        self.assertEqual(merge([(1, 3), (3, 4)]), [(1, 4)])

    def test_disjoint_sorted(self):
        self.assertEqual(
            merge([(1, 2), (4, 5), (7, 9)]), [(1, 2), (4, 5), (7, 9)])

    def test_unsorted_merges_and_sorts(self):
        self.assertEqual(
            merge([(3, 5), (1, 2), (5, 7)]), [(1, 2), (3, 7)])

    def test_chain_overlap(self):
        self.assertEqual(
            merge([(1, 4), (2, 6), (5, 8)]), [(1, 8)])

    def test_same_start(self):
        self.assertEqual(merge([(1, 3), (1, 5)]), [(1, 5)])

    def test_single(self):
        self.assertEqual(merge([(2, 3)]), [(2, 3)])

    def test_empty_input(self):
        self.assertEqual(merge([]), [])

    def test_empty_windows_dropped(self):
        self.assertEqual(
            merge([(1, 1), (2, 4), (3, 3)]), [(2, 4)])

    def test_all_empty_input(self):
        self.assertEqual(merge([(1, 1), (2, 2)]), [])

    def test_negative_touching(self):
        self.assertEqual(
            merge([(-2, 0), (0, 2), (1, 3)]), [(-2, 3)])

    def test_reversed_raises_value_error(self):
        with self.assertRaises(ValueError):
            merge([(1, 2), (5, 3)])

    def test_reversed_single_window(self):
        with self.assertRaises(ValueError):
            merge([(5, 3)])

    def test_input_list_not_mutated(self):
        windows = [(1, 3), (5, 7), (2, 4)]
        original = [list(w) for w in windows]
        merge(windows)
        self.assertEqual(windows, original)

    def test_iterator_input(self):
        self.assertEqual(
            merge([(1, 3), (2, 4), (3, 3), (5, 9)]), [(1, 4), (5, 9)])

    def test_tuple_of_windows(self):
        self.assertEqual(merge(((1, 3), (3, 4))), [(1, 4)])

    def test_zero_length_between_positive(self):
        self.assertEqual(merge([(0, 0), (0, 5)]), [(0, 5)])


if __name__ == "__main__":
    unittest.main()
